-- ============================================================================
-- SOURCE: 20261003_remove_jlpt_listening_examples.sql
-- ============================================================================
-- Loại bỏ các câu mẫu 例／れい bị nhập nhầm thành câu thi Choukai.
-- Các bảng đáp án và audio clip liên quan được xóa theo khóa ngoại ON DELETE CASCADE.
START TRANSACTION;

DELETE q
FROM jlpt_question q
JOIN jlpt_mondai m ON m.id = q.mondai_id
JOIN jlpt_part p ON p.id = m.part_id
WHERE p.part_code = 'listening'
  AND REPLACE(REPLACE(TRIM(q.question_text), ' ', ''), '　', '') IN
      ('れい', '例', '(れい)', '（れい）', '(例)', '（例）', '(例(れい))', '（例（れい））');

COMMIT;

-- ============================================================================
-- SOURCE: 20261004_jlpt_sentence_order.sql
-- ============================================================================
-- Non-destructive upgrade: store option numbers in their correct left-to-right order.
SET @ddl = IF(
    EXISTS (SELECT 1 FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='jlpt_question' AND COLUMN_NAME='correct_order'),
    'SELECT 1', 'ALTER TABLE jlpt_question ADD COLUMN correct_order JSON NULL AFTER correct_option'
);
PREPARE jlpt_order_stmt FROM @ddl;
EXECUTE jlpt_order_stmt;
DEALLOCATE PREPARE jlpt_order_stmt;

-- Reviewed sentence-composition keys for N3 July 2025 (source question IDs).
-- Do not overwrite an order already entered by a content administrator.
UPDATE jlpt_question q
JOIN jlpt_mondai m ON m.id=q.mondai_id
JOIN jlpt_part p ON p.id=m.part_id
JOIN jlpt_exam e ON e.id=p.exam_id
SET q.correct_order = CASE q.source_question_id
    WHEN 12014 THEN '[1,3,4,2]'
    WHEN 12015 THEN '[3,4,2,1]'
    WHEN 12016 THEN '[4,2,1,3]'
    WHEN 12017 THEN '[2,4,3,1]'
    WHEN 12018 THEN '[3,2,4,1]'
END
WHERE e.exam_code='N3_2025_07' AND q.source_question_id IN (12014,12015,12016,12017,12018)
  AND UPPER(m.format_code)='SENTENCE_COMPOSITION' AND q.correct_order IS NULL;

-- ============================================================================
-- SOURCE: 20261005_jlpt_sentence_order_data.sql
-- ============================================================================
-- Incremental JLPT sentence-order data upgrade. No tables are reset.
-- Run 20261004_jlpt_sentence_order.sql first. Preserve orders already saved by an administrator.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
START TRANSACTION;
-- N5_MOCK_1#11834
