-- ============================================================================
-- Installation verification
-- ============================================================================
SELECT e.jlpt_level,
       COUNT(DISTINCT e.id) AS exam_count,
       COUNT(q.id) AS question_count
FROM jlpt_exam e
LEFT JOIN jlpt_part p ON p.exam_id = e.id
LEFT JOIN jlpt_mondai m ON m.part_id = p.id
LEFT JOIN jlpt_question q ON q.mondai_id = m.id
GROUP BY e.jlpt_level
ORDER BY e.jlpt_level;

SELECT COUNT(*) AS audio_clip_count,
       SUM(clip_type = 'INFERRED') AS inferred_audio_clip_count
FROM jlpt_audio_clip;

SELECT COUNT(*) AS exam_count, 84 AS expected_exam_count FROM jlpt_exam;
SELECT COUNT(*) AS question_count, 8596 AS expected_question_count FROM jlpt_question;
SELECT COUNT(*) AS sentence_order_count, 418 AS expected_sentence_order_count
FROM jlpt_question WHERE correct_order IS NOT NULL;

SET SQL_SAFE_UPDATES = @JLPT_OLD_SQL_SAFE_UPDATES;
